import { useState } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyValues: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(emptyValues);

  const isLastStep = step === steps.length - 1;

  const setField =
    (field: keyof RegistrationValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
      const next = event.target.value;
      setValues((current) => ({ ...current, [field]: next }));
    };

  const summary: Array<[string, string]> = [
    ['Имя', values.name],
    ['Электронная почта', values.email],
    ['Телефон', values.phone],
    ['Город', values.city],
    ['Улица и дом', values.street],
    ['Индекс', values.zip],
  ];

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (isLastStep) {
          onSubmit(values);
        } else {
          setStep((current) => Math.min(current + 1, steps.length - 1));
        }
      }}
      style={{ display: 'grid', gap: '24px', fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxInputField
            label="Имя"
            required
            value={values.name}
            onChange={setField('name')}
            placeholder="Анна Смирнова"
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={setField('email')}
            helperText="На неё придёт письмо с подтверждением"
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={values.phone}
            onChange={setField('phone')}
            placeholder="900 123-45-67"
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxInputField
            label="Город"
            required
            value={values.city}
            onChange={setField('city')}
            placeholder="Москва"
          />
          <JxInputField
            label="Улица и дом"
            required
            value={values.street}
            onChange={setField('street')}
            placeholder="Тверская, 12, кв. 5"
          />
          <JxInputField
            label="Индекс"
            value={values.zip}
            onChange={setField('zip')}
            placeholder="101000"
            helperText="Шесть цифр"
          />
        </div>
      )}

      {step === 2 && (
        <div
          style={{
            display: 'grid',
            gap: '12px',
            padding: '16px',
            background: 'var(--jx-surface-2)',
            border: '1px solid var(--jx-border)',
            borderRadius: 'var(--jx-r)',
          }}
        >
          {summary.map(([label, value]) => (
            <div
              key={label}
              style={{ display: 'flex', justifyContent: 'space-between', gap: '16px' }}
            >
              <span style={{ color: 'var(--jx-text-3)' }}>{label}</span>
              <span style={{ color: 'var(--jx-text)', textAlign: 'right' }}>
                {value || '—'}
              </span>
            </div>
          ))}
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton
          variant="ghost"
          type="button"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(current - 1, 0))}
        >
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

